import org.jetbrains.uast.UClass;
import org.jetbrains.uast.UElement;
import org.jetbrains.uast.UField;
import org.jetbrains.uast.visitor.UastVisitor;

import java.util.Collections;
import java.util.List;

public class ParcelDetector extends Detector implements Detector.SourceCodeScanner {

    private static final Implementation IMPLEMENTATION =
            new Implementation(ParcelDetector.class, Scope.JAVA_FILE_SCOPE);

    public static final Issue ISSUE = Issue.create(
            "ParcelCreator",
            "Missing `Parcelable` `CREATOR` field",
            "Classes that implement `android.os.Parcelable` are required to have a " +
            "non-null static field named `CREATOR` that implements " +
            "`android.os.Parcelable.Creator`.",
            Category.CORRECTNESS,
            6,
            Severity.ERROR,
            IMPLEMENTATION
    );

    @Nullable
    @Override
    public List<Class<? extends UElement>> getApplicableUastTypes() {
        return Collections.singletonList(UClass.class);
    }

    @Nullable
    @Override
    public UElementHandler createUastHandler(@NotNull JavaContext context) {
        return new UElementHandler() {
            @Override
            public void visitClass(@NotNull UClass node) {
                if (node.isInterface()) {
                    return;
                }
                if (node.hasModifierProperty(PsiModifier.ABSTRACT)) {
                    return;
                }
                if (!context.getEvaluator().implementsInterface(node, "android.os.Parcelable", false)) {
                    return;
                }

                for (UField field : node.getFields()) {
                    if ("CREATOR".equals(field.getName())
                            && field.hasModifierProperty(PsiModifier.STATIC)
                            && context.getEvaluator().typeMatches(field.getType(), "android.os.Parcelable.Creator")) {
                        return;
                    }
                }

                context.report(ISSUE, node, context.getNameLocation(node),
                        "This class implements `Parcelable` but does not define a static `CREATOR` field");
            }
        };
    }
}
```

